mkdir -p "$TMPDIR/chk" && cat > "$TMPDIR/chk/check.py" <<'EOF'
import csv, sys, os, re
from datetime import date, timedelta
D = sys.argv[1]; P = date(2026,11,27)
d = lambda s: date.fromisoformat(s)
read = {}
def rows(f):
    with open(os.path.join(D,f), newline='') as h:
        lines = [l for l in h if not l.startswith('#')]
    r = list(csv.DictReader(lines)); read[f] = len(r); return r
def txt(f):
    t = open(os.path.join(D,f)).read().splitlines(); read[f] = len(t); return t
C = rows('contracts_register_2026.csv'); start = {r['id']: d(r['start_date']) for r in C}
ids = sorted(start)
F, G = [], []
def add(lid, rule, who, n=None): F.append((lid, rule, sorted(set(who)), n))
# L02
R = {r['id']: d(r['date_filed']) for r in rows('registration_M1M2_2026.csv')}
add('L02','M1/M2 später als Tag vor Beginn',[i for i in ids if i not in R or R[i] > start[i]-timedelta(1)])
for i in ids:
    if i in R and R[i] == start[i]-timedelta(1): G.append(('L02',i,'eingereicht genau am Tag vor Beginn'))
# L05/L06
O = rows('overtime_weekly_2026.csv')
over = [r for r in O if int(r['overtime_hours']) > 8]
add('L05','Überstunden über 8 h/Woche',[r['id'] for r in over], len(over))
for r in O:
    if int(r['overtime_hours']) == 8: G.append(('L05',r['id'],'genau 8 h'))
M = txt('meldungen_ueberstunden_ordner.txt')
signed2026 = [l for l in M if l.startswith('2026-') and re.search(r'Unterschrift:\s*\S', l)]
ot = [r for r in O if int(r['overtime_hours']) > 0]
add('L06','Überstundenwoche ohne Meldung',[r['id'] for r in ot] if not signed2026 else [], len(ot) if not signed2026 else 0)
# L07
PL = rows('payroll_lines_2026-07_to_10.csv')
otm = {(r['id'], r['week_start'][:7]) for r in ot}
miss = [r for r in PL if (r['id'], r['month']) in otm and int(r['overtime_line_hours']) == 0]
add('L07','Lohnzeile ohne Überstundenzeile',[r['id'] for r in miss], len(miss))
# L04
A = rows('attendance_2026-11.csv')
bad = [r for r in A if not r['code'] and (not r['start'] or not r['end'])]
add('L04','Anwesenheit ohne Beginn/Ende',[r['id'] for r in bad], len(bad))
for i in sorted({r['id'] for r in A if r['code']}): G.append(('L04',i,'Zeilen mit Code ABS, Abwesenheit, kein Arbeitstag'))
# L08 (nur Wochenende verschiebt; Feiertagsliste NICHT IN DATEIEN)
late = []
for r in rows('payroll_runs_2026.csv'):
    dl = d(r['period_end'])+timedelta(15); sh = dl
    while sh.weekday() >= 5: sh += timedelta(1)
    if d(r['pay_date']) > sh: late.append(r['period_end'])
    elif d(r['pay_date']) > dl: G.append(('L08',r['period_end'],f'Frist {dl} fällt aufs Wochenende, verschoben auf {sh}'))
add('L08','Lohn später als 15 Tage',late, len(late))
# L09
LD = {r['id']: int(r['days']) for r in rows('leave_decisions_2026.csv')}
due = lambda s: date(s.year+(s.month+5)//12, (s.month+5)%12+1, min(s.day,28)) if False else None
def plus6(s):
    m = s.month+6; y = s.year+(m-1)//12; m = (m-1)%12+1
    return date(y, m, min(s.day, 28 if m==2 else 30 if m in (4,6,9,11) else 31))
add('L09','Urlaubsbescheid fehlt oder unter 20 Tagen',[i for i in ids if plus6(start[i]) <= P and LD.get(i,0) < 20])
for i in ids:
    if plus6(start[i]) > P and i not in LD: G.append(('L09',i,f'6 Monate erst am {plus6(start[i])}, noch nicht geschuldet'))
rows('absences_2026.csv')
# L03
E = rows('employee_records_2026.csv')
emp = [r for r in E if any(not r[f'f{k:02}'].strip() for k in range(1,23))]
add('L03','leere Felder in der Akte',[r['id'] for r in emp], sum(1 for r in E for k in range(1,23) if not r[f'f{k:02}'].strip()))
# L12
def minus24(p): return date(p.year-2, p.month, p.day)
ME = {r['id']: d(r['last_exam_date']) for r in rows('medical_exams.csv')}
add('L12','Untersuchung älter als 24 Monate',[i for i in ids if i not in ME or ME[i] < minus24(P)])
for i in ids:
    if i in ME and minus24(P) <= ME[i] <= minus24(P)+timedelta(31): G.append(('L12',i,f'Untersuchung {ME[i]}, noch innerhalb 24 Monate'))
# L10
S = txt('sicherheitserklaerung_2019.md')
listed = {l[2:].strip() for l in S if l.startswith('- ')}
add('L10','Stellenbezeichnung fehlt in Sicherheitserklärung',sorted({r['role'] for r in C} - listed))
# L13
T = {r['id']: r for r in rows('training_proofs_2026.csv')}
new = [i for i in ids if date(2025,11,27) <= start[i] < P]
add('L13','Unterweisung fehlt oder nach Einstellungstag',[i for i in new if i not in T or d(T[i]['training_date']) > start[i]])
for i in new:
    if i in T and d(T[i]['training_date']) == start[i]: G.append(('L13',i,'Unterweisung am Einstellungstag'))
    if i in T and d(T[i]['training_date']) < start[i]: G.append(('L13',i,'Unterweisung vor Einstellungstag'))
txt('ordner-index.md')
print('GELESEN', read)
for f in F:
    if f[2]: print('FUND', f[0], f[1], 'betroffen:', ' '.join(f[2]), 'Zahl:', len(f[2]), '' if f[3] is None else f'(Zeilen/Wochen/Felder: {f[3]})')
for g in G: print('GRENZ', *g)
print('SUMME', sum(read.values()), sum(1 for f in F if f[2]), len(G))
EOF
python3 -I "$TMPDIR/chk/check.py" "$PWD"
